import{_ as a,a as t,o as d,ai as s}from"./chunks/framework.BbOtTPsL.js";const u=JSON.parse('{"title":"Save Cart Addresses","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cart-save-address","title":"Save Cart Addresses","description":"Save billing (and optionally shipping) addresses on the draft cart.","query":"mutation SaveAddress($input: saveAddressAdminCartInput!) {\\n  saveAddressAdminCart(input: $input) {\\n    adminCart { itemsCount grandTotal formattedGrandTotal success message }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/carts/314\\",\\n    \\"cartId\\": \\"314\\",\\n    \\"billing\\": {\\n      \\"firstName\\": \\"Jane\\",\\n      \\"lastName\\": \\"Doe\\",\\n      \\"email\\": \\"jane@example.com\\",\\n      \\"address\\": [\\"12 Main St\\"],\\n      \\"city\\": \\"Berlin\\",\\n      \\"country\\": \\"DE\\",\\n      \\"state\\": \\"BE\\",\\n      \\"postcode\\": \\"10115\\",\\n      \\"phone\\": \\"+4930123456\\",\\n      \\"useForShipping\\": true\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"saveAddressAdminCart\\": {\\n      \\"adminCart\\": { \\"itemsCount\\": 1, \\"grandTotal\\": 100, \\"formattedGrandTotal\\": \\"$100.00\\", \\"success\\": true, \\"message\\": \\"Address saved.\\" }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/carts/save-address.md","filePath":"api/graphql-api/admin/sales/carts/save-address.md","lastUpdated":1781099665000}'),r={name:"api/graphql-api/admin/sales/carts/save-address.md"};function n(o,e,i,c,l,p){return d(),t("div",null,e[0]||(e[0]=[s('<h1 id="save-cart-addresses" tabindex="-1">Save Cart Addresses <a class="header-anchor" href="#save-cart-addresses" aria-label="Permalink to &quot;Save Cart Addresses&quot;">​</a></h1><p>GraphQL counterpart of <code>POST /api/admin/carts/{id}/addresses</code>. Mutation field is <code>saveAddressAdminCart</code>.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative cart id. Admin cart endpoints only operate on <strong>draft carts</strong> (<code>is_active=0</code>) — storefront carts are rejected by the admin cart guard. Create a draft cart first with the <a href="./../../customers/create-draft-cart.html"><code>createAdminDraftCart</code></a> mutation and use the returned <code>cartId</code>.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>saveAddressAdminCart(input: saveAddressAdminCartInput!)</code></td><td>Mutation</td></tr></tbody></table><h2 id="required-fields" tabindex="-1">Required fields <a class="header-anchor" href="#required-fields" aria-label="Permalink to &quot;Required fields&quot;">​</a></h2><p>Each address (billing always; shipping too when <code>useForShipping</code> is <code>false</code>) must include <code>firstName</code>, <code>lastName</code>, <code>email</code>, <code>address</code> (a non-empty array of street lines), <code>city</code>, <code>country</code>, <code>state</code>, <code>postcode</code> and <code>phone</code>, otherwise the mutation fails with a <code>422</code>-equivalent error. <code>companyName</code> is optional.</p>',7)]))}const h=a(r,[["render",n]]);export{u as __pageData,h as default};
